INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group) VALUES ('NK1', 'Chin tuck (подбородок назад)', 'neck', 'isometric', 'none', NULL, NULL, 'reps', 0, 'Затылок тянется вверх и назад, подбородок скользит к горлу. Двойной подбородок — это правильно. Держать 5 секунд.', NULL, NULL, 1, 'neck_flex');
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group) VALUES ('NK2', 'Изометрия сгибания шеи', 'neck', 'isometric', 'none', NULL, NULL, 'seconds', 0, 'Ладонь на лоб, голова давит в ладонь, но не двигается. 30–50% усилия.', 'Давить в полную силу и задерживать дыхание.', NULL, 1, 'neck_iso');
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group) VALUES ('NK3', 'Изометрия разгибания шеи', 'neck', 'isometric', 'none', NULL, NULL, 'seconds', 0, 'Ладони на затылок, давление назад. Шея нейтральна.', NULL, NULL, 1, 'neck_iso');
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group) VALUES ('NK4', 'Изометрия вбок', 'neck', 'isometric', 'none', NULL, NULL, 'seconds', 1, 'Ладонь на висок. Плечо не поднимается.', 'Подъём плеча к уху вместо работы шеи.', NULL, 1, 'neck_iso');
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group) VALUES ('NK5', 'Изометрия ротации', 'neck', 'isometric', 'none', NULL, NULL, 'seconds', 1, 'Ладонь на скулу, попытка повернуть голову против сопротивления.', NULL, NULL, 1, 'neck_iso');
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group) VALUES ('NK6', 'Растяжка верхней трапеции', 'neck', 'stretch', 'none', NULL, NULL, 'seconds', 1, 'Сидя, рука той же стороны под бедром. Ухо к плечу, мягко помочь рукой.', NULL, NULL, 1, 'neck_stretch');
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group) VALUES ('NK7', 'Растяжка леватора лопатки', 'neck', 'stretch', 'none', NULL, NULL, 'seconds', 1, 'То же, что NK6, но нос к подмышке — тянет заднюю поверхность шеи.', NULL, NULL, 1, 'neck_stretch');
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group) VALUES ('NK8', 'Подъём головы лёжа', 'neck', 'isometric', 'none', NULL, NULL, 'reps', 0, 'Сначала chin tuck, потом оторвать голову на 2 см.', 'Голова трясётся — уменьшить время удержания.', NULL, 1, 'neck_flex');
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group) VALUES ('NK9', 'Разгибатели лёжа на животе', 'neck', 'isometric', 'none', NULL, NULL, 'seconds', 0, 'Лоб на кулаках, приподнять голову, взгляд в пол.', 'Запрокидывать голову назад.', NULL, 1, 'neck_ext');
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group) VALUES ('NK10', 'Дыхание 90/90', 'neck', 'isometric', 'wall', NULL, NULL, 'reps', 0, 'Голени на стуле, поясница прижата. Вдох 4 с в нижние рёбра, выдох 6 с.', NULL, NULL, 1, 'breathing');
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group) VALUES ('SC1', 'Prone Y', 'scap', 'pull', 'none', NULL, NULL, 'reps', 0, 'Лёжа на животе, руки под 45°, большие пальцы вверх. Поднять за счёт нижней трапеции, плечи от ушей.', NULL, NULL, 1, 'scap_raise');
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group) VALUES ('SC2', 'Prone T', 'scap', 'pull', 'none', NULL, NULL, 'reps', 0, 'Руки в стороны, свести лопатки, поднять.', 'Прогиб в пояснице вместо работы лопаток.', NULL, 1, 'scap_raise');
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group) VALUES ('SC3', 'Prone W', 'scap', 'pull', 'none', NULL, NULL, 'reps', 0, 'Локти у рёбер, свести лопатки и приподнять локти.', NULL, NULL, 1, 'scap_raise');
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group) VALUES ('SC4', 'Скольжение по стене', 'scap', 'mobility', 'wall', NULL, NULL, 'reps', 0, 'Спина, затылок и предплечья у стены, скольжение вверх без отрыва. Честный тест подвижности грудного отдела.', 'Отрыв предплечий или поясницы от стены ради амплитуды.', NULL, 1, 'scap_control');
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group) VALUES ('SC5', 'Face pull с резиной', 'scap', 'pull', 'band', NULL, NULL, 'reps', 0, 'Тянуть к переносице, локти выше кистей, в конце — внешняя ротация.', NULL, NULL, 1, 'scap_raise');
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group) VALUES ('SC6', 'Halo с гирей', 'scap', 'mobility', 'kettlebell', NULL, NULL, 'reps', 1, 'Гиря дном вверх, круг вокруг головы близко к ней.', 'Шея тянется за гирей.', NULL, 1, 'scap_mobility');
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group) VALUES ('SC8', 'Вис на турнике', 'scap', 'isometric', 'bar', NULL, NULL, 'seconds', 0, 'Свободный вис, плечи активны. Разгружает грудной и шейный отдел.', NULL, NULL, 1, 'decompression');
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group) VALUES ('SC9', 'Пуловер лёжа', 'scap', 'pull', 'kettlebell', NULL, NULL, 'reps', 0, 'Руки прямые, гиря за голову до натяжения широчайших. Рёбра вниз, поясница прижата.', NULL, NULL, 1, 'lat_stretch');
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group) VALUES ('SC10', 'Обратная «муха» в наклоне', 'scap', 'pull', 'kettlebell', NULL, NULL, 'reps', 0, 'Наклон 45°, гири в стороны. Средняя трапеция и задняя дельта. 5 кг здесь — рабочий вес.', NULL, NULL, 1, 'scap_raise');
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group) VALUES ('RW1', 'Тяга одной рукой в наклоне', 'row', 'pull', 'kettlebell', 'row', 1, 'reps', 1, 'Опора рукой на стул, спина параллельна полу и прямая. Тянуть к поясу, локоть вдоль тела.', NULL, NULL, 1, 'horizontal_row');
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group) VALUES ('RW2', 'Тяга двумя гирями («горилла»)', 'row', 'pull', 'kettlebell', 'row', 1, 'reps', 0, 'Гири между стоп, наклон, поочерёдная тяга.', 'Таз разворачивается за рукой.', NULL, 1, 'horizontal_row');
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group) VALUES ('RW5', 'Тяга лёжа на животе', 'row', 'pull', 'kettlebell', 'row', 1, 'reps', 1, 'Лёжа на животе на кровати, тяга гири вниз-вверх. Полностью снимает нагрузку с поясницы — вариант для дня боли в спине.', NULL, NULL, 1, 'horizontal_row');
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group) VALUES ('RW6', 'Подтягивания', 'row', 'pull', 'bar', 'row', 7, 'reps', 0, 'Без рывков шеей, подбородок нейтрален. Оставлять 2 повтора в запасе.', NULL, NULL, 1, 'vertical_pull');
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group) VALUES ('RW7', 'Тяга под столом (австралийская)', 'row', 'pull', 'wall', 'row', 4, 'reps', 0, 'Лечь под устойчивый стол, взяться за край, тянуть грудь к краю. Тело в линию. Уровень регулируется углом и положением ног.', NULL, NULL, 1, 'horizontal_row');
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group) VALUES ('RW8', 'Тяга рюкзака в наклоне', 'row', 'pull', 'backpack', 'row', 3, 'reps', 1, 'Рюкзак с книгами за лямку. Вес регулируется книгами — это основной способ увеличить нагрузку в тягах.', NULL, NULL, 1, 'horizontal_row');
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group) VALUES ('PC1', 'Румынская тяга двумя ногами', 'posterior', 'hinge', 'kettlebell', 'hinge', 2, 'reps', 0, 'Таз назад, колени мягкие, гири скользят вдоль бедра. Диапазон — до границы прямой спины.', 'Приседать вместо наклона; круглить поясницу ради глубины.', NULL, 1, 'hinge_bilateral');
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group) VALUES ('PC2', 'Румынская тяга на одной ноге', 'posterior', 'hinge', 'kettlebell', 'hinge', 3, 'reps', 1, 'Свободная нога назад в линию с корпусом, таз не заваливается. Диапазон — до границы прямой спины, а не до пола.', NULL, NULL, 1, 'hinge_uni');
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group) VALUES ('PC3', 'Свинг двумя руками', 'posterior', 'hinge', 'kettlebell', NULL, NULL, 'reps', 0, 'Не подъём руками, а удар тазом. В верхней точке ягодицы и пресс жёсткие, шея нейтральна.', 'Поднимать гирю плечами; приседать вместо тазового шарнира.', NULL, 1, 'swing');
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group) VALUES ('PC4', 'Свинг одной рукой', 'posterior', 'hinge', 'kettlebell', 'hinge', 6, 'reps', 1, 'То же движение, что PC3, но одной рукой: корпус не разворачивается, свободная рука работает в такт.', 'Ротация корпуса за гирей.', NULL, 1, 'swing');
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group) VALUES ('PC5', 'Good morning с гирей у груди', 'posterior', 'hinge', 'kettlebell', 'hinge', 1, 'reps', 0, 'Наклон с прямой спиной. База для освоения тазового шарнира.', NULL, NULL, 1, 'hinge_light');
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group) VALUES ('PC6', 'Superman', 'posterior', 'hinge', 'none', NULL, NULL, 'reps', 0, 'Одновременный подъём рук и ног. Шея — продолжение позвоночника.', NULL, NULL, 1, 'back_ext');
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group) VALUES ('PC7', 'Bird dog', 'core', 'isometric', 'none', 'core', 2, 'reps', 1, 'Противоположные рука и нога, таз не качается.', NULL, NULL, 1, 'core_stability');
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group) VALUES ('PC8', 'Ягодичный мостик на одной ноге', 'posterior', 'hinge', 'none', NULL, NULL, 'reps', 1, 'Полное разгибание бедра, пауза 1 с сверху.', NULL, NULL, 1, 'hip_ext');
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group) VALUES ('PC9', 'Становая с рюкзаком', 'posterior', 'hinge', 'backpack', 'hinge', 5, 'reps', 0, 'Рюкзак с книгами за лямки. Спина прямая, толкать пол ногами.', NULL, NULL, 1, 'hinge_heavy');
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group) VALUES ('PR1', 'Жим стоя одной рукой', 'press', 'push', 'kettlebell', NULL, NULL, 'reps', 1, 'С 5 кг — упражнение на технику и здоровье плеча, не на силу. Рёбра вниз, бицепс у уха.', NULL, NULL, 0, 'overhead_press');
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group) VALUES ('PR3', 'Отжимания', 'press', 'push', 'none', 'push', 4, 'reps', 0, 'Тело в линию, лопатки свободно двигаются.', 'Голова тянется вперёд; провисает поясница.', NULL, 1, 'horizontal_press');
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group) VALUES ('PR4', 'Жим лёжа на полу', 'press', 'push', 'kettlebell', NULL, NULL, 'reps', 0, 'Локти под 45°. Вариант для дня, когда отжимания не идут.', NULL, NULL, 1, 'horizontal_press');
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group) VALUES ('PR5', 'Внешняя ротация лёжа на боку', 'press', 'pull', 'kettlebell', NULL, NULL, 'reps', 1, 'Локоть прижат к боку под 90°, предплечье поднимается вверх. Ротаторам 5 кг — это уже много, начинать можно без веса.', NULL, NULL, 1, 'rotator');
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group) VALUES ('PR6', 'Отведение в наклоне (Y-raise стоя)', 'press', 'pull', 'kettlebell', NULL, NULL, 'reps', 0, 'Наклон 30°, руки вверх под 45° большими пальцами вверх.', NULL, NULL, 1, 'scap_raise');
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group) VALUES ('LG2', 'Выпад назад', 'legs', 'squat', 'none', 'squat', 4, 'reps', 1, 'Колено мягко касается пола, корпус вертикально.', NULL, NULL, 1, 'lunge');
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group) VALUES ('LG4', 'Болгарский присед', 'legs', 'squat', 'none', 'squat', 5, 'reps', 1, 'Задняя нога на стуле. Тяжелее, чем кажется — начинать без веса.', NULL, NULL, 1, 'lunge');
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group) VALUES ('LG5', 'Присед с весом тела', 'legs', 'squat', 'none', 'squat', 1, 'reps', 0, 'Пятки на полу, колени по направлению стоп, спина прямая.', 'Отрыв пяток — тогда каблук на книгу и MB8 в мобилити.', NULL, 1, 'squat');
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group) VALUES ('LG6', 'Присед на одной ноге к стулу', 'legs', 'squat', 'none', 'squat', 7, 'reps', 1, 'Опускание на стул на одной ноге. Вершина лестницы приседов дома.', NULL, NULL, 1, 'squat');
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group) VALUES ('LG7', 'Подъём на носки на одной ноге', 'legs', 'squat', 'none', NULL, NULL, 'reps', 1, 'Полная амплитуда, пауза сверху. Важно при длинных голенях.', NULL, NULL, 1, 'calf');
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group) VALUES ('CR1', 'Планка', 'core', 'isometric', 'none', 'core', 3, 'seconds', 0, 'Таз подвёрнут, шея нейтральна, взгляд в пол.', NULL, NULL, 1, 'core_iso');
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group) VALUES ('CR2', 'Боковая планка', 'core', 'isometric', 'none', 'core', 5, 'seconds', 1, 'Тело в линию, верхняя рука вверх.', NULL, NULL, 1, 'core_iso');
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group) VALUES ('CR3', 'Чемоданная переноска', 'core', 'carry', 'kettlebell', NULL, NULL, 'steps', 1, 'Гиря в одной руке, корпус строго вертикально, плечо не проваливается.', NULL, NULL, 1, 'carry');
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group) VALUES ('CR4', 'Фермерская переноска', 'core', 'carry', 'kettlebell', NULL, NULL, 'steps', 0, 'Две гири, плечи назад и вниз, шаги короткие.', NULL, NULL, 1, 'carry');
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group) VALUES ('CR5', 'Turkish get-up', 'core', 'complex', 'kettlebell', NULL, NULL, 'reps', 1, 'Полный подъём с пола с гирей над головой. С 5 кг — идеальный вес для освоения. Только со свежими силами.', NULL, NULL, 0, 'complex');
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group) VALUES ('CR6', 'Dead bug', 'core', 'isometric', 'none', 'core', 1, 'reps', 1, 'Поясница прижата к полу всё время. Медленно, с выдохом.', NULL, NULL, 1, 'core_stability');
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group) VALUES ('CR7', 'Rack carry', 'core', 'carry', 'kettlebell', NULL, NULL, 'steps', 1, 'Гиря в стойке на груди. Учит держать корпус и лопатку.', NULL, NULL, 1, 'carry');
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group) VALUES ('CR8', 'Переноска рюкзака с правильной посадкой', 'core', 'carry', 'backpack', NULL, NULL, 'steps', 0, 'Лямки затянуты высоко, между лопаток. Осознанная отработка того, что ломается в жизни.', NULL, NULL, 1, 'carry');
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group) VALUES ('MB1', 'Разгибание грудного отдела на валике', 'mobility', 'mobility', 'wall', NULL, NULL, 'reps', 0, 'Свёрнутое полотенце поперёк спины под лопатками, руки за головой, мягкий прогиб.', 'Прогибаться поясницей вместо грудного отдела.', NULL, 1, 't_spine');
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group) VALUES ('MB2', 'Open book', 'mobility', 'mobility', 'none', NULL, NULL, 'reps', 1, 'Лёжа на боку, верхняя рука раскрывается назад, взгляд за рукой.', NULL, NULL, 1, 't_spine');
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group) VALUES ('MB3', 'Cat-cow', 'mobility', 'mobility', 'none', NULL, NULL, 'reps', 0, 'Плавно, включая шейный отдел.', NULL, NULL, 1, 'spine_flow');
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group) VALUES ('MB4', 'Растяжка груди в дверном проёме', 'mobility', 'stretch', 'wall', NULL, NULL, 'seconds', 1, 'Предплечье на косяке, локоть на уровне плеча, шаг вперёд.', NULL, NULL, 1, 'pec_stretch');
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group) VALUES ('MB5', 'World''s greatest stretch', 'mobility', 'mobility', 'none', NULL, NULL, 'reps', 1, 'Выпад плюс ротация корпуса с рукой вверх.', NULL, NULL, 1, 'hip_mobility');
